practice.solution:
n = int(input())
parent = {}
for _ in range(n):
    child, par = input().split()
    parent[child] = par

q = int(input())
for _ in range(q):
    name = input().strip()
    if name != 'root' and name not in parent:
        print(f'{name}: not found')
        continue
    chain = [name]
    while chain[-1] != 'root':
        chain.append(parent[chain[-1]])
    chain.reverse()
    print(' > '.join(chain) + f' [depth {len(chain) - 1}]')
